import {paths} from './assets/icons.js';
const $ = (s) => document.querySelector(s);
const icon = (name) => `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${name==='more'?'<path d="M5 12h.01M12 12h.01M19 12h.01" stroke-width="3"/>':paths[name] || paths.info}</svg>`;
const mark = `<svg class="mark" viewBox="0 0 100 100" role="img" aria-label="Sidefolk"><g fill="currentColor"><ellipse cx="37" cy="33" rx="10.5" ry="25" transform="rotate(-9 37 33)"/><ellipse cx="63.5" cy="36" rx="10" ry="22" transform="rotate(9 63.5 36)"/><ellipse cx="50" cy="67" rx="33" ry="24.5"/></g><g class="eyes"><circle cx="40" cy="65" r="3.6"/><circle cx="60" cy="65" r="3.6"/></g><circle class="signal" cx="86" cy="17" r="7.5"/></svg>`;
const brand = () => `<div class="brand">${mark}<span>sidefolk</span></div>`;
const pet = (pose='idle',name='pip',cls='') => `<img class="${cls}" src="assets/${name}-${pose}.webp" alt="${name==='pip'?'Pip':'Spark'}, ${pose==='idle'?'resting':pose}">`;
const statusWords={idle:'Idle',think:'Thinking',work:'Working',alert:'Needs you',done:'Done',failed:'Failed',sleep:'Asleep'};
const status=(s)=>`<span class="status" data-state="${s}"><span class="glyph">${icon(s)}</span>${statusWords[s]}</span>`;
const btn=(text,action,style='')=>`<button class="btn ${style}" data-action="${action}">${text}</button>`;
const routeBtn=(text,screen,style='')=>`<button class="btn ${style}" data-go="${screen}">${text}</button>`;
const ib=(name,label,action)=>`<button class="icon-button" aria-label="${label}" data-action="${action}">${icon(name)}</button>`;
const sectionHead=(title,link='',screen='')=>`<div class="section-head"><h2>${title}</h2>${link?routeBtn(link,screen,'quiet'):''}</div>`;
const head=(title,sub,action='')=>`<div class="page-head"><div><h1 tabindex="-1">${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;
const input=(id,label,value,type='text')=>`<label class="label" for="${id}">${label}</label><input class="field" id="${id}" type="${type}" value="${value}">`;
const toggle=(label,on=true)=>`<button role="switch" aria-label="${label}" aria-checked="${on}" class="switch" data-action="toggle"></button>`;
const setting=(title,description,control)=>`<div class="setting-row"><div><strong>${title}</strong>${description?`<p>${description}</p>`:''}</div>${control}</div>`;
const specs = [
['cover','The workday desk','The design direction: a useful daily place with a recognizable Sidefolk identity.'],
['today','Today · connected','A time-led agenda. One distinct decision surface. Real recent writing, rather than notebook containers.'],
['calm','Today · everyday','The same useful product with no AI tools connected. No technical vocabulary or connection promotions.'],
['reminders','Reminders','List first. Due times and repeats remain visible. Completion and More are the two row actions.'],
['reminder-edit','Reminder · editor','Explicit schedule, occurrence scope and timezone. Snooze moves one occurrence; the series anchor stays put.'],
['work-log','Work log','Notebook navigation, readable dated entries, inline capture and a visible destination.'],
['week','Your week','A factual weekly record of notes and completed reminders. Copy as Markdown; no invented productivity score.'],
['sessions','Sessions','Project, first prompt line and host identify each session. Completed work can be logged deliberately.'],
['request','Request · complete operation','The exact operation is prominent. No default approval. Handoff and expiry remain visible.'],
['request-diff','Request · edit diff','The actual before/after change stays readable, with the file path and session identity beside it.'],
['setup','Setup · first reminder','Value before configuration. Pip helps create one real reminder, with its resolved time shown.'],
['setup-notifications','Setup · permissions','Permission results are explicit. Denied notifications have a useful, honest consequence and recovery.'],
['setup-tools','Setup · optional tools','One optional connection step. Waiting for the first live event is separate from an installation result.'],
['settings','Settings · General','A separate macOS-style settings window with four panes, outside the daily task navigation.'],
['companion','Settings · Companion','Pip and Spark keep their shipped identities. Character choice changes appearance, never capabilities.'],
['agents','Settings · Agents','One connection flow, honest health, and the host capability matrix. Codex is clearly beta.'],
['privacy','Settings · Privacy & data','Local data, retention and export are understandable. Destructive actions are separated from daily work.'],
['desktop','Desktop · companion moments','Tail-linked cards, the shipped character, one short sentence, and generous 44px controls.'],
['components','Design system','An implementation palette, native type hierarchy, shared components and state vocabulary.'],
['states','Recovery & edge states','Loading, empty, error, stale, unavailable and released states each explain the next useful action.'],
['quick-add','Quick add','One shared input, an explicit interpretation and a visible destination. Capture finishes where it starts.'],
['today-dark','Today · dark','The same hierarchy in the existing warm dark palette. No information depends on color alone.'],
['settings-dark','Settings · dark','Native controls and readable layers follow the selected appearance.'],
['narrow','Today · compact','At 720px, full navigation labels remain visible and the content follows its priority order.'],
['repeat-editor','Reminder · repeating series','Choose the occurrence or all future reminders, with a visible weekly anchor and unchanged future dates after snooze.'],
['quick-reminder','Quick add · reminder preview','A resolved date, time, zone and destination appear before saving.'],
['quick-ambiguity','Quick add · ambiguous time','An ambiguous hour becomes a choice. It is never silently guessed.'],
['notebook-choice','Quick add · notebook choice','Several near matches become an explicit destination choice. The note draft remains intact.'],
['request-released','Request · released','Expired or handed-off requests lose their answer controls and show where to continue.'],
['request-long','Request · long operation','Unread content has a clear boundary. Allow is absent until the complete operation has been shown.'],
['desktop-spark','Desktop · Spark','The alternative companion uses the same card language and 44px controls; the logo stays unchanged.'],
['control-states','Design system · interaction states','Hover, focus, disabled, pending, validation and persistent Undo are designed alongside the default controls.'],
['new-reminder','Reminder · create','A fresh reminder starts with a blank title and real date/time values, then shows the resolved schedule.'],
['setup-disconnected','Setup · connection choice','The disconnected state offers Connect; the installed state separately waits for a real first event.']
];
const params=new URLSearchParams(location.search);
let screen=params.get('screen') || '';
let theme=params.get('theme') || (screen.endsWith('-dark')?'dark':'light');
let demo={noteDraft:'',notebook:'All entries',quiet:false,pet:'pip',request:null,completed:new Set(),notes:[],week:false};
const titles=Object.fromEntries(specs.map(([s,t])=>[s,t]));
function sidebar(active,calm=false){return `<aside class="sidebar"><div><div class="traffic" aria-hidden="true"><i></i><i></i><i></i></div>${brand()}</div><nav class="nav" aria-label="Main">${[['today','home','Today'],...calm?[]:[['sessions','terminal','Sessions']],['reminders','reminders','Reminders'],['work-log','notes','Work log']].map(([s,i,t])=>`<button data-go="${s}" ${s===active?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${s==='sessions'?'<span class="count">2</span>':''}</button>`).join('')}</nav><div class="sidebar-foot"><div class="companion-dock">${pet('idle',demo.pet)}<p><strong>${demo.pet==='pip'?'Pip':'Spark'}</strong>Here if you need me.</p></div><div class="utility"><button class="row quiet-state" data-action="quiet" aria-pressed="${demo.quiet}">${icon(demo.quiet?'sleep':'idle')}<span>${demo.quiet?'Quiet is on':'Quiet'}</span></button><button class="icon-button" aria-label="Open Settings" data-go="settings">${icon('settings')}</button></div></div></aside>`;}
function shell(content,active='today',calm=false){return `<div class="window">${sidebar(active,calm)}<main class="content"><header class="toolbar"><span class="breadcrumb">${active==='today'?'Your day, at a glance':titles[active] || 'Sidefolk'}</span><button class="quick-launch" data-action="quick">${icon('plus')}<span>Quick add</span><kbd>⌘ K</kbd></button></header><div class="page">${content}</div></main></div>`;}
function agendaRow(time,title,detail,id){return `<div class="agenda-row"><time>${time}</time><div class="grow"><strong>${title}</strong><span class="meta">${detail}</span></div><button class="check ${demo.completed.has(id)?'done':''}" aria-label="Complete ${title}" aria-pressed="${demo.completed.has(id)}" data-complete="${id}"></button><button class="icon-button" aria-label="Details for ${title}" data-go="reminder-edit">${icon('chevron')}</button></div>`;}
function today(calm=false,empty=false){return shell(`${head('Today','Sunday, 25 October',routeBtn(`${icon('plus')} Add reminder`,'new-reminder'))}<div class="today-grid"><div>${calm?`<div class="empty-day">${pet('wave')}<div><h2>A little space for your day.</h2><p>Your reminders and small wins, kept together.</p></div></div>`:`<section class="section">${sectionHead('Overdue')}<div class="overdue-row"><button class="check" aria-label="Complete Book the dentist" data-complete="dentist"></button><div class="grow"><strong>Book the dentist</strong><small>Today 09:00 · Overdue</small></div>${routeBtn('Details','reminder-edit','quiet')}</div></section><section class="section">${sectionHead('Needs you','All sessions','sessions')}<div class="attention"><div class="row identity">${pet('alert','pip','pet-avatar')}<span>sidefolk · Claude Code</span>${status('alert')}</div><h2>Run project tests?</h2><p>“Tighten reminder parsing” · Terminal.app</p>${routeBtn(`Review request ${icon('next')}`,'request','primary')}</div></section>`}<section class="section">${sectionHead("Today's reminders",'All reminders','reminders')}<div class="agenda">${agendaRow('15:00','Review launch notes','Once · Today','launch')}${agendaRow('18:00','Call Mum','Every Sunday','mum')}${calm?agendaRow('20:00','Put the bins out','Every Sunday','bins'):''}</div></section>${calm?`<button class="capture-hint" data-action="quick">${icon('plus')}<span>Make room for one small thought.</span><span class="grow"></span>⌘ K</button>`:''}</div><aside class="today-aside">${calm?'':`<section class="section">${sectionHead('Running sessions')}<div class="session-small"><div class="row between"><strong>website</strong>${status('work')}</div><p>Refine the pricing page</p><div class="row between"><span class="meta">Claude Code · iTerm2</span>${btn('Open','open-session','quiet')}</div></div></section>`}<section class="section">${sectionHead('Recent log','Work log','work-log')}<article class="quiet-note"><time>Today, 11:42 · Log</time><p class="note-title">The small details are starting to feel right.</p><p class="meta">Simplified the welcome flow. One reminder before any setup.</p></article><article class="quiet-note"><time>Yesterday, 17:10 · Sidefolk</time><p class="note-title">A quieter way to ask.</p><p class="meta">Keep the full action visible. Let Pip carry the personality.</p></article><button class="capture-hint" data-action="note">${icon('notes')}<span>Keep a thought</span><span class="grow"></span>${icon('plus')}</button></section></aside></div>`, 'today',calm);}
const reminderRows = (selected=false) => `<div class="list-header"><strong>Overdue</strong><span>1 reminder</span></div><div class="list-item"><button class="check" aria-label="Complete Book the dentist" data-complete="dentist"></button><div class="grow"><strong>Book the dentist</strong><span class="meta error-copy">Today 09:00 · Overdue</span></div>${ib('more','More for Book the dentist','more-reminder')}</div><div class="list-header"><strong>Today</strong><span>Sunday, 25 Oct</span></div><div class="list-item ${selected?'selected':''}"><button class="check" aria-label="Complete Review launch notes" data-complete="launch"></button><button class="grow" data-go="reminder-edit" style="text-align:left"><strong>Review launch notes</strong><span class="meta">Once</span></button><span class="list-time">15:00</span>${ib('more','More for Review launch notes','more-reminder')}</div><div class="list-item"><button class="check" aria-label="Complete Call Mum" data-complete="mum"></button><button class="grow" data-go="reminder-edit" style="text-align:left"><strong>Call Mum</strong><span class="meta">Every Sunday</span></button><span class="list-time">18:00</span>${ib('more','More for Call Mum','more-reminder')}</div><div class="list-header"><strong>Tomorrow</strong><span>Monday, 26 Oct</span></div><div class="list-item"><button class="check" aria-label="Complete Plan the week" data-complete="plan"></button><div class="grow"><strong>Plan the week</strong><span class="meta">Every Monday</span></div><span class="list-time">09:00</span>${ib('more','More for Plan the week','more-reminder')}</div><div class="list-header"><strong>Later</strong><span>1 reminder</span></div><div class="list-item"><button class="check" aria-label="Complete Renew the domain" data-complete="domain"></button><div class="grow"><strong>Renew the domain</strong><span class="meta">Once · Thu, 29 Oct</span></div><span class="list-time">10:00</span>${ib('more','More for Renew the domain','more-reminder')}</div>`;
function reminders(edit=false){const list=`${head('Reminders','Small things, at the right time.',edit?'':routeBtn(`${icon('plus')} Add reminder`,'new-reminder','primary'))}<div class="filter-row"><div class="segmented" role="group" aria-label="Reminder filter"><button aria-pressed="true" data-action="filter-active">Upcoming</button><button aria-pressed="false" data-action="filter-repeat">Repeating</button><button aria-pressed="false" data-action="filter-completed">Completed</button></div></div><div id="reminder-list">${reminderRows(edit)}</div>`;return shell(edit?`<div class="sheet-layout"><section class="sheet-main">${list}</section><aside class="detail-pane" aria-label="Reminder details"><div class="row between"><span class="eyebrow">Edit reminder</span><button class="icon-button" data-go="reminders" aria-label="Close reminder editor">${icon('failed')}</button></div><div class="spacer"></div><div class="form"><div>${input('rem-title','Reminder','Review launch notes')}</div><div class="field-row"><div>${input('rem-date','Date','2026-10-25','date')}</div><div>${input('rem-time','Time','15:00','time')}</div></div><div><label class="label" for="rem-repeat">Repeat</label><select id="rem-repeat" class="field"><option>Does not repeat</option><option>Daily</option><option>Weekdays</option><option>Weekly</option><option>Every N days or weeks…</option><option>Monthly</option><option>Yearly</option></select></div><p class="form-hint">Time zone · Asia/Tokyo</p><div class="preview"><strong>Today, 25 Oct at 15:00</strong>Asia/Tokyo · This reminder appears on this Mac.</div><div class="row">${btn('Save changes','save-reminder','primary')}${routeBtn('Cancel','reminders')}</div></div><div class="divider"></div><h3>Snooze this occurrence</h3><p class="form-hint">Move this reminder without changing its title.</p><div class="suggestions">${btn('10 min','snooze')}${btn('1 hour','snooze')}${btn('This evening','snooze')}${btn('Tomorrow 9:00','snooze')}${btn('Pick…','snooze-pick')}</div><div class="divider"></div><h3>History</h3><p class="form-hint">Created today at 11:30</p><div class="spacer"></div>${btn('Delete reminder…','delete-reminder','danger')}</aside></div>`:list,'reminders');}
const noteEntry=(time,title,text,book='Log')=>`<article class="entry" data-notebook="${book}"><time>${time}</time><div><div class="row between"><button data-action="edit-note" style="font-weight:620;text-align:left">${title}</button><span class="pill outline">${book}</span></div><p>${text}</p><div class="row">${btn('Move','move-note','quiet')}${ib('more',`More for ${title}`,'more-note')}</div></div></article>`;
function log(){return shell(`${head('Work log','A place for what you want to remember.',routeBtn('Your week '+icon('next'),'week','quiet'))}<div class="row"><label for="log-search" class="sr-only">Search entries</label><input class="field" id="log-search" placeholder="Search entries, October, last week…" aria-label="Search entries by text or date"><button class="btn project-filter" data-action="project-filter">All projects ${icon('chevron')}</button></div><div class="notebook-grid"><aside class="notebooks" aria-label="Notebooks">${[['All entries','notes'],['Log','notes'],['Sidefolk','folder'],['Ideas','notes']].map(([n,i])=>`<button data-book="${n}" aria-current="${demo.notebook===n}">${icon(i)}${n}</button>`).join('')}<p class="eyebrow">Your notebooks</p><button class="new-book" data-action="new-notebook">${icon('plus')} New notebook</button></aside><section><div class="notebook-title"><h2 id="notebook-name">${demo.notebook}</h2>${btn('Copy as Markdown','copy-notebook','quiet')}</div><div class="note-capture"><button class="row between" style="width:100%;text-align:left" data-action="compose-log"><span>Add a note to <strong>${demo.notebook==='All entries'?'Log':demo.notebook}</strong></span><span class="row">New entry ${icon('plus')}</span></button><div id="note-editor" hidden><label class="label" for="new-note">Note</label><textarea id="new-note" placeholder="A thought, a decision, a small win…"></textarea><div class="row between"><span class="meta">Private Markdown, on this Mac.</span>${btn('Save note','save-note','primary')}</div></div></div><div class="list-header"><strong>This week · 19–25 Oct</strong><span>3 entries</span></div><div id="log-entries">${noteEntry('11:42','The welcome flow','Simplified the welcome flow. One reminder before any setup. Less explanation, something useful sooner.')}${noteEntry('Sat<br>17:10','A quieter way to ask','Keep the full action visible. Let Pip carry the personality.','Sidefolk')}${noteEntry('Fri<br>16:28','The first useful minute','A person should leave setup with a reminder that actually works.','Ideas')}</div></section></div>`,'work-log');}
function week(){return shell(`${head('Your week','19–25 October 2026',btn(`${icon('copy')} Copy as Markdown`,'copy-week','primary'))}<div class="week-strip"><div><strong>Three things you kept. Two things you finished.</strong><p class="meta">Entries and completed reminders from this week.</p></div>${pet('note','pip','pet-avatar')}</div><div class="today-grid"><section>${sectionHead('From your work log')}<article class="week-entry"><span class="meta">Sunday, 25 Oct · Log</span><h3>The welcome flow</h3><p>One reminder before any setup. Something useful sooner.</p></article><article class="week-entry"><span class="meta">Saturday, 24 Oct · Sidefolk</span><h3>A quieter way to ask</h3><p>Keep the full action visible. Let Pip carry the personality.</p></article><article class="week-entry"><span class="meta">Friday, 23 Oct · Ideas</span><h3>The first useful minute</h3><p>A person should leave setup with a reminder that works.</p></article></section><aside>${sectionHead('Completed reminders')}<div class="week-entry"><div class="row">${icon('done')}<strong>Send the beta invitation</strong></div><p>Friday, 23 Oct · 10:00</p></div><div class="week-entry"><div class="row">${icon('done')}<strong>Back up the project</strong></div><p>Thursday, 22 Oct · 18:00</p></div><div class="callout">Your week is a plain record. Entries stay as you wrote them.</div>${routeBtn('Back to Work log','work-log','quiet')}</aside></div>`,'work-log');}
function sessions(){return shell(`${head('Sessions','A clear way back to the work that needs you.')}<div class="section-head"><h2>Needs you</h2><span class="meta">1 request</span></div><div class="session-list-row selected"><div><strong>sidefolk</strong><p>Tighten reminder parsing</p><span class="meta">Claude Code · Terminal.app · ttys004</span></div>${status('alert')}<div class="actions">${routeBtn('Review','request','primary')}${btn('Open','open-session','quiet')}</div></div><div class="spacer"></div>${sectionHead('Running')}<div class="session-list-row"><div><strong>website</strong><p>Refine the pricing page</p><span class="meta">Claude Code · iTerm2 · ttys006</span></div>${status('work')}<div class="actions">${btn('Open','open-session')}</div></div><div class="spacer"></div>${sectionHead('Finished')}<div class="session-list-row"><div><strong>docs</strong><p>Make the setup guide easier to follow</p><span class="meta">Claude Code · Terminal.app · Today 13:10</span></div>${status('done')}<div class="actions">${btn('Log it','log-session','quiet')}${btn('Continue','continue-session')}</div></div><p class="footnote">Opening a waiting session moves its request to Claude’s own prompt.</p>`,'sessions');}
function request(diff=false){return shell(`${head('Review request','The complete action, before you decide.',routeBtn('All sessions','sessions','quiet'))}<div class="request-grid"><aside class="request-context"><div class="row">${pet('alert','pip','pet-avatar')}${status('alert')}</div><h3>sidefolk</h3><p class="meta">Tighten reminder parsing</p><dl><div><dt>Tool</dt><dd>Claude Code</dd></div><div><dt>Host</dt><dd>Terminal.app · ttys004</dd></div><div><dt>Session</dt><dd class="mono">a19f…7c32</dd></div><div><dt>Project folder</dt><dd class="mono">~/Git/sidefolk</dd></div></dl></aside><section class="request-content"><span class="eyebrow">${diff?'Edit file':'Run command'}</span><h2>${diff?'Update the reminder label?':'Run project tests?'}</h2><p class="muted">${diff?'Claude Code is asking to change this exact text.':'Claude Code is asking to run the command below.'}</p><p class="path" style="margin-top:20px">${diff?'src/dashboard/reminders.ts':'Working folder · /Users/you/Git/sidefolk'}</p>${diff?`<div class="ops-diff" aria-label="Complete proposed diff"><div class="meta">@@ line 84 @@</div><div class="removed">− label.textContent = "Tomorrow";</div><div class="added">+ label.textContent = describeDue(reminder.due);</div></div>`:`<pre aria-label="Complete command">npm test</pre>`}<div class="row"><span class="pill">${icon('done')} Complete operation shown</span><span class="meta">${diff?'1 change · 2 lines':'8 characters'}</span></div><div class="request-foot" id="request-decision">${demo.request?`<div class="request-state"><strong>${demo.request}</strong><p class="meta">Demo only. No answer was sent to a tool.</p></div>`:`<div class="row">${btn('Decline','decline')}${btn('Allow once','allow','primary')}${btn('Answer in terminal','answer-terminal','quiet')}</div><p class="safe-note">Claude waits about a minute, then asks in your terminal.</p>`}</div></section></div>`,'sessions');}
function settingsShell(content,active='General'){return `<div class="settings-window"><aside class="settings-sidebar"><div class="traffic" aria-hidden="true"><i></i><i></i><i></i></div><h2>Settings</h2><nav class="nav" aria-label="Settings">${[['General','settings','settings'],['Companion','crew','companion'],['Agents','terminal','agents'],['Privacy & data','info','privacy']].map(([title,i,to])=>`<button data-go="${to}" ${active===title?'aria-current="page"':''}>${icon(i)}<span>${title}</span></button>`).join('')}</nav></aside><main class="settings-content">${content}</main></div>`;}
function settings(){return settingsShell(`<h1 tabindex="-1">General</h1><p class="muted">Make Sidefolk fit the way you work.</p><section class="settings-section"><h2>Appearance</h2><div class="setting-row"><div><strong>Theme</strong><p>System follows your Mac.</p></div><div class="theme-choice">${['System','Light','Dark'].map(t=>`<button class="theme-option ${t==='Dark'?'dark':''} ${t.toLowerCase()===theme?'active':''}" data-theme-choice="${t.toLowerCase()}" aria-pressed="${t.toLowerCase()===theme}"><span class="mini"></span><span>${t}</span></button>`).join('')}</div></div>${setting('Text size','Keep every view comfortable to read.','<select class="field" aria-label="Text size" style="width:120px"><option>Default</option><option>Larger</option></select>')}${setting('Reduce motion','Keep pose changes and transitions still.',toggle('Reduce motion',false))}</section><section class="settings-section"><h2>Every day</h2>${setting('Start at login','Keep reminders ready when your Mac starts.',toggle('Start at login'))}${setting('Show in Dock','Closing the window keeps Sidefolk running.',toggle('Show in Dock'))}${setting('Sound cues','One chime when something needs you.',toggle('Sound cues'))}${setting('Default snooze','Move one occurrence, not the repeating schedule.','<select class="field" aria-label="Default snooze" style="width:120px"><option>10 minutes</option><option>1 hour</option></select>')}${setting('Your week','A quiet look back at what you kept and finished.','<button class="btn" data-action="week-setting">Friday 16:00</button>')}</section><section class="settings-section"><h2>Shortcuts & Labs</h2>${setting('Quick add','Open the same input from anywhere.','<span class="pill outline">⌘ ⇧ Space</span>')}${setting('Labs','Optional beta features are off by default.',btn('Show Labs','labs','quiet'))}</section>`);}
function companion(){return settingsShell(`<h1 tabindex="-1">Companion</h1><p class="muted">A familiar face, by your side.</p><div class="companion-picker">${[['pip','Pip'],['spark','Spark']].map(([n,t])=>`<button class="pet-choice" aria-pressed="${demo.pet===n}" data-pet="${n}">${pet('idle',n)}<strong>${t}</strong></button>`).join('')}</div><p class="meta">Same reminders, notes and questions. Choose the face you like.</p><section class="settings-section">${setting('Name','Used when your companion speaks.','<input class="field" aria-label="Companion name" style="width:180px" value="'+(demo.pet==='pip'?'Pip':'Spark')+'">')}${setting('Size','Character size is independent of card text.','<select class="field" aria-label="Companion size" style="width:180px"><option>Default · 150 px</option><option>Small</option><option>Large</option></select>')}${setting('Position','Drag your companion to a comfortable spot.',btn('Reset position','reset-position'))}${setting('Sleep when you’re away','Your companion rests after two idle minutes.',toggle('Sleep when away'))}</section><div class="callout">The clay character appears when it speaks. The Pip Signal mark stays the Sidefolk logo.</div><div class="row">${pet('note',demo.pet)}<p class="meta">“Noted.”<br>Short, factual and never in a hurry.</p></div>`,'Companion');}
function agents(){return settingsShell(`<h1 tabindex="-1">Agents</h1><p class="muted">A small bridge to your own tools.</p><section class="settings-section"><h2>Claude Code</h2>${setting('Connect Claude Code','Hooks and MCP together. Changes are backed up.',toggle('Connect Claude Code'))}<div class="preview" style="margin-top:16px"><strong>Working</strong>Last event today at 14:31 · sidefolk</div>${setting('Default terminal','For continuing an ended session.','<select class="field" aria-label="Default terminal" style="width:160px"><option>Terminal.app</option><option>iTerm2</option></select>')}</section><section class="settings-section"><h2>Where Open takes you</h2><div class="setting-row"><strong>Terminal.app / iTerm2</strong><span class="meta">Exact tab (tty)</span></div><div class="setting-row"><strong>Ghostty 1.3+</strong><span class="meta">Bring forward + select the session there</span></div><div class="setting-row"><strong>VS Code / Cursor</strong><span class="meta">Project window, else app</span></div><div class="setting-row"><strong>tmux / ssh / unknown</strong><span class="meta">Copy attach command</span></div>${btn('Full host capability matrix','host-matrix','quiet')}</section><section class="settings-section"><h2>Codex <span class="pill outline">Beta</span></h2>${setting('Codex activity','Turn-finished signals depend on the supported adapter.',btn('Set up…','codex-setup'))}<p class="footnote">Sidefolk does not answer Codex approvals.</p></section><div class="callout">Sidefolk shows the last received event so you can tell the connection is working.</div>`,'Agents');}
function privacy(){return settingsShell(`<h1 tabindex="-1">Privacy & data</h1><p class="muted">Your work stays yours.</p><div class="callout"><strong>On this Mac</strong><br>Reminders, settings and Markdown notebooks are stored locally. The journal keeps only the first prompt line for 7 days. It never stores commands or tool inputs.</div><section class="settings-section"><h2>Desktop privacy</h2>${setting('Hide from screen recordings','Protection depends on the capture tool.',toggle('Hide from screen recordings'))}</section><section class="settings-section"><h2>Your data</h2>${setting('Session journal','First prompt line only. You can switch it off.',toggle('Session journal'))}${setting('Keep journal for','Reminders and notebooks are separate.','<select class="field" aria-label="History retention" style="width:140px"><option>7 days</option><option>Off</option></select>')}${setting('Clear session history','Keeps your reminders and notebooks.',btn('Clear…','clear-history'))}${setting('Export','Copy notebooks and Your week as Markdown.',btn('Export…','export'))}${setting('Copy report','Preview first. Home paths, names and tokens are redacted.',btn('Preview report…','report'))}</section><section class="settings-section"><h2>Disconnect</h2>${setting('Disconnect & uninstall','Remove Sidefolk’s integrations. Keep data by default.',btn('Disconnect & uninstall…','uninstall','danger'))}</section><p class="footnote">Data leaves this Mac only through an explicitly chosen external action.</p>`,'Privacy & data');}
function setup(step=1){const stepData={1:['Your first small reminder.','Make one thing easier to remember. You can change it any time.'],2:['Ready when you need it.','Choose how Sidefolk stays available on this Mac.'],3:['Do you use Claude Code?','Connect when you want your work sessions here. Reminders and your work log already work.']}[step];return `<div class="setup-window"><aside class="setup-art">${brand()}${pet(step===1?'wave':step===2?'note':'idle')}<p class="art-caption">${step===1?'A little help,<br>by your side.':step===2?'“I’ll hold that<br>for you.”':'“Here if you<br>need me.”'}</p></aside><main class="setup-form"><div class="setup-progress" aria-label="Step ${step} of 3">${[1,2,3].map(s=>`<i class="${s<=step?'active':''}"></i>`).join('')}</div><span class="eyebrow">Step ${step} of 3</span><h1 tabindex="-1">${stepData[0]}</h1><p>${stepData[1]}</p>${step===1?`<div class="form"><div>${input('first-reminder','Reminder','Take a screen break')}</div><div class="field-row"><div>${input('first-date','Date','2026-10-25','date')}</div><div>${input('first-time','Time','15:00','time')}</div></div><div class="preview"><strong>Today, 25 Oct at 15:00</strong>Asia/Tokyo · Reminders appear on this Mac.</div></div>${routeBtn('Save reminder & continue '+icon('next'),'setup-notifications','primary')}`:step===2?`<div class="form"><div class="setup-result">${icon('info')}<div class="grow"><strong>Notifications are off</strong><p>Reminders show only while Sidefolk is running.</p></div>${btn('Open Settings','notification-settings','quiet')}</div><div class="setup-result">${icon('done')}<div class="grow"><strong>Start at login is on</strong><p>Sidefolk starts with your Mac.</p></div>${toggle('Start at login')}</div></div>${routeBtn('Continue '+icon('next'),'setup-tools','primary')}<p class="footnote">Demo state: permissions are not requested by this prototype.</p>`:`<div class="form"><div class="preview"><strong>Connected and waiting for the first session</strong>Setup files are installed. Open Claude Code to verify a live event.</div>${btn('Open Claude Code','open-claude','primary')}<p class="form-hint">Waiting for the first live event. ${btn('Review connection…','connect','quiet')}</p></div>${routeBtn('Skip, I don’t use AI tools','calm','quiet')}<div class="spacer"></div>${routeBtn('Continue to Today','today')}`}</main></div>`;}
function desktop(){return `<div class="desktop-board"><section class="desktop-cell"><span class="eyebrow">01 / A reminder arrives · light wallpaper</span><div class="bubble-scene">${pet('note')}<div class="bubble"><span class="meta">Reminder · Today 15:00</span><h3>Review launch notes</h3><p>I kept this for you.</p><div class="row">${btn('Done','overlay-done','primary')}${btn('Snooze','overlay-snooze')}</div></div></div></section><section class="desktop-cell dark"><span class="eyebrow">02 / A complete, short request · dark wallpaper</span><div class="bubble-scene">${pet('alert')}<div class="bubble"><div class="row between"><span class="meta">sidefolk · Claude Code</span>${status('alert')}</div><h3>Run project tests?</h3><span class="meta mono">~/Git/sidefolk · Terminal.app</span><pre>npm test</pre><div class="row">${btn('Decline','decline')}${btn('Allow once','allow','primary')}</div>${btn('Answer in terminal','answer-terminal','quiet')}<p>Claude waits about a minute, then asks in your terminal.</p></div></div></section><section class="desktop-cell"><span class="eyebrow">03 / Capture, without opening the window</span><div class="bubble-scene">${pet('write1')}<div class="bubble"><label class="label" for="overlay-quick">Quick add</label><input id="overlay-quick" class="field" value="note: Keep the first step useful"><p>Save to Log · This Mac</p><div class="row">${btn('Save note','overlay-note','primary')}${btn('Discard','discard')}</div></div></div></section><section class="desktop-cell"><span class="eyebrow">04 / Quiet access · no companion required</span><div class="menu-preview"><p><strong>Sidefolk</strong><span class="meta">1 needs you</span></p><hr><p>Show Sidefolk <span>⌘ O</span></p><p>Hide Pip</p><p>Quick add <span>⌘ ⇧ Space</span></p><hr><p>Pause answers</p><p>Settings… <span>⌘ ,</span></p><p>Disconnect & uninstall…</p><hr><p>Quit Sidefolk <span>⌘ Q</span></p></div></section></div>`;}
function components(){return shell(`${head('A familiar visual language','Warm surfaces. Useful contrast. One vocabulary.')}<div class="system-grid"><section class="system-panel"><h2>01 · Palette</h2><div class="swatches">${[['#f7f3ea','Canvas'],['#fffcf7','Surface'],['#272a33','Ink'],['#6fcfb4','Mint'],['#c87658','Accent']].map(([c,t])=>`<div class="swatch" style="background:${c};color:${c==='#272a33'?'#f7f3ea':'#272a33'}">${t}</div>`).join('')}</div><p class="footnote">Existing semantic tokens, unchanged in this proposal.</p></section><section class="system-panel"><h2>02 · Typography</h2><div class="type-samples"><strong>Today</strong><span>28 / Panel</span></div><div class="row"><h2 style="font-size:20px">A small thing, kept.</h2><span class="meta">20 / Section</span></div><p style="margin-top:12px">13 / Window body · 12 / Supporting · <code>13 / Raw operation</code></p></section><section class="system-panel"><h2>03 · Controls</h2><div class="component-rows"><div class="row">${btn('Save reminder','demo','primary')}${btn('Cancel','demo')}${btn('Delete…','demo','danger')}</div><div class="row"><div class="segmented"><button aria-pressed="true">Upcoming</button><button>Completed</button></div>${toggle('Example setting')}</div><p class="meta">28px window controls · 44px overlay controls · 3px focus ring</p></div></section><section class="system-panel"><h2>04 · States</h2><div class="status-set">${Object.keys(statusWords).map(status).join('')}</div><p class="footnote">A glyph and a word carry meaning; the fill is decorative.</p></section><section class="system-panel"><h2>05 · List row</h2>${agendaRow('15:00','Review launch notes','Once · Today','component-row')}<p class="footnote">Hairline separation. Two row actions at most.</p></section><section class="system-panel"><h2>06 · Capture & confirmation</h2><label class="label" for="component-note">Quick add</label><input id="component-note" class="field" value="note: Less setup, more useful"><div class="preview" style="margin-top:12px"><strong>Save a note to Log</strong>Noted in Log · Move · Undo</div></section></div>`,'today');}
function states(){return shell(`<div class="states-page">${head('Every state has a way forward','Every moment has a useful next step.')}<div class="state-grid"><section class="state-sample"><span class="eyebrow">Empty</span><h3>No reminders yet.</h3><p>Keep one small thing for later.</p>${routeBtn('Add reminder','new-reminder','quiet')}</section><section class="state-sample"><span class="eyebrow">Loading</span><h3>Loading reminders…</h3><div class="skeleton"></div><div class="skeleton short"></div><p>Your reminders are being loaded.</p></section><section class="state-sample"><span class="eyebrow">Error · preserved data</span><h3>I couldn’t read your reminders file.</h3><p>Your file was kept as it was. Nothing was overwritten.</p><div class="row">${btn('Restore last good copy','restore','quiet')}${btn('Show in Finder','finder','quiet')}</div></section><section class="state-sample"><span class="eyebrow">Stale</span><h3>Showing the last saved version.</h3><p>The latest changes haven’t loaded. Last updated 14:20.</p>${btn('Retry','retry','quiet')}</section><section class="state-sample"><span class="eyebrow">Request released</span><h3>Moved to your terminal.</h3><p>Claude is asking there. This request can’t be allowed here.</p>${btn('Open session','open-session','quiet')}</section><section class="state-sample"><span class="eyebrow">While you were away</span><h3>Two reminders arrived while you were away.</h3><p>Book the dentist · Today 09:00 · Late<br>Plan the week · Yesterday 09:00 · Late</p>${routeBtn('Review reminders','reminders','quiet')}</section><section class="state-sample"><span class="eyebrow">Notifications denied</span><h3>Reminders show only while Sidefolk is running.</h3><p>They appear on this Mac.</p>${btn('Open notification settings','notification-settings','quiet')}</section><section class="state-sample"><span class="eyebrow">Connection health</span><h3>Claude Code needs repair.</h3><p>The connection files changed. We kept the backup.</p>${btn('Repair…','repair','quiet')}</section></div></div>`,'today');}
function cover(){return `<div class="cover"><img src="assets/desk-cover.png" alt="A folded note in a mint tray beside a cream notebook; presentation artwork"><div class="cover-copy">${brand()}<span class="eyebrow">Experience design · 25 October 2026</span><h1>The workday<br>desk.</h1><p>A small place for what needs you,<br>what’s next, and what’s worth keeping.</p><p class="caption">Product flows · Visual system · Desktop moments<br>Editable prototype · Developer handoff</p></div></div>`;}
function quickModal(initial='note: Keep the first step useful',showNow=true){let dialog=document.createElement('dialog');dialog.className='quick-dialog';dialog.setAttribute('aria-label','Quick add');dialog.innerHTML=`<div class="row between"><h2>Quick add</h2><button class="icon-button" data-close aria-label="Close Quick add">${icon('failed')}</button></div><label class="label" for="quick-text">Remind me…, note…, open…</label><input class="field" id="quick-text" autocomplete="off"><div class="suggestions">${btn('Remind me tomorrow at 9','suggest-reminder')}${btn('Note to Log','suggest-note')}</div><div class="preview" id="quick-preview"><strong>Save a note to Log</strong>Visible destination · Private Markdown on this Mac.</div><p class="form-hint" id="quick-explanation">The preview shows what will be saved, and where.</p><div class="dialog-actions"><button class="btn" data-close>Discard</button><button class="btn primary" id="quick-save">Save note</button></div>`;document.body.append(dialog);dialog.querySelector('input').value=initial;dialog.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>dialog.close());dialog.querySelector('[data-action=suggest-reminder]').onclick=()=>{dialog.querySelector('input').value='Remind me tomorrow at 9 to review the draft';updateQuick(dialog)};dialog.querySelector('[data-action=suggest-note]').onclick=()=>{dialog.querySelector('input').value='note: ';updateQuick(dialog)};dialog.querySelector('input').oninput=()=>updateQuick(dialog);dialog.querySelector('input').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();dialog.querySelector('#quick-save').click()}};dialog.querySelector('#quick-save').onclick=()=>{const v=dialog.querySelector('input').value.trim();if(!v){dialog.querySelector('#quick-text').setAttribute('aria-invalid','true');dialog.querySelector('#quick-preview').textContent='Add a reminder or a note first.';return}if(v.startsWith('$')){dialog.querySelector('#quick-preview').textContent='Commands are off. Turn on in Settings → General → Labs.';return}dialog.close();toast((dialog.dataset.savedLabel||'Preview confirmed')+' · Demo only','Undo')};dialog.onclose=()=>dialog.remove();dialog.showModal();dialog.querySelector('input').focus();updateQuick(dialog);}
function updateQuick(dialog){dialog.dataset.savedLabel='Noted in Log';const text=dialog.querySelector('input').value;const p=dialog.querySelector('#quick-preview');const save=dialog.querySelector('#quick-save');p.replaceChildren();const strong=document.createElement('strong');if(text.startsWith('$')){strong.textContent='Commands are off';p.append(strong,'Turn on in Settings → General → Labs.');save.textContent='Commands off';save.disabled=true;}else if(/\bat 3\b/i.test(text)){strong.textContent='Which 3 o’clock?';p.append(strong);const choices=document.createElement('div');choices.className='suggestions';for(const choice of ['15:00 today','03:00 tomorrow']){const b=document.createElement('button');b.className='btn';b.textContent=choice;b.onclick=()=>{p.replaceChildren();strong.textContent=choice+' · Asia/Tokyo';dialog.dataset.savedLabel='Reminder saved for '+choice;p.append(strong,'This reminder appears on this Mac.');save.disabled=false;save.textContent='Save reminder';};choices.append(b)}p.append(choices);save.textContent='Choose a time';save.disabled=true;}else if(/^note for Evaluation:/i.test(text)){strong.textContent='Which notebook?';p.append(strong,'Your draft is kept while you choose.');const choices=document.createElement('div');choices.className='suggestions';for(const name of ['Evaluation H1 2026','Evaluation H2 2026','Log']){const b=document.createElement('button');b.className='btn';b.textContent=name;b.onclick=()=>{p.replaceChildren();strong.textContent='Save a note to '+name;dialog.dataset.savedLabel='Noted in '+name;p.append(strong,'Prefer the simpler flow');save.textContent='Save note';save.disabled=false;};choices.append(b)}p.append(choices);save.textContent='Choose a notebook';save.disabled=true;}else if(/tomorrow|remind/i.test(text)){strong.textContent='Reminder · Mon, 26 Oct at 09:00';dialog.dataset.savedLabel='Reminder saved for Mon, 26 Oct at 09:00';p.append(strong,'Asia/Tokyo · This Mac · Demo interpretation');save.textContent='Save reminder';save.disabled=false;}else{strong.textContent='Save a note to Log';p.append(strong,'Visible destination · Private Markdown on this Mac.');save.textContent='Save note';save.disabled=false;}}
function toast(text,undo=''){document.querySelectorAll('.toast').forEach(t=>t.remove());let t=document.createElement('div');t.className='toast';t.setAttribute('role','status');let msg=document.createElement('span');msg.textContent=text;t.append(msg);if(undo){let u=document.createElement('button');u.textContent=undo;u.onclick=()=>{t.remove();toast('Change undone · Demo only')};t.append(u)}let close=document.createElement('button');close.className='dismiss';close.textContent='×';close.setAttribute('aria-label','Dismiss message');close.onclick=()=>{t.remove();$('.quick-launch')?.focus()};t.append(close);($('.window')||$('.settings-window')||$('.board')).append(t);}
function action(name,el){if(name==='compose-log'){$('#note-editor').hidden=false;$('#new-note').focus();return}if(name==='quick'||name==='note'){quickModal(name==='note'?'note: ':'');return}if(name==='toggle'){el.setAttribute('aria-checked',el.getAttribute('aria-checked')!=='true');return}if(name==='quiet'){demo.quiet=!demo.quiet;render();return}if(name==='allow'||name==='decline'){demo.request=name==='allow'?'Allowed once · Demo only':'Declined · Demo only';if(screen==='request'||screen==='request-diff'){render();$('#request-decision').setAttribute('tabindex','-1');$('#request-decision').focus()}else toast(demo.request);return}if(name==='answer-terminal'){demo.request='Moved to your terminal · Demo only';render();return}if(name==='save-note'){const field=$('#new-note');if(!field.value.trim()){field.focus();return}const ent=document.createElement('article');ent.className='entry';ent.innerHTML='<time>14:32</time><div><strong>Just added</strong><p></p></div>';ent.querySelector('p').textContent=field.value.trim();$('#log-entries').prepend(ent);field.value='';demo.noteDraft='';toast(`Noted in ${demo.notebook==='All entries'?'Log':demo.notebook} · Demo only`,'Undo');return}if(name==='filter-active'||name==='filter-repeat'||name==='filter-completed'){el.parentElement.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));$('#reminder-list').innerHTML=name==='filter-active'?reminderRows():name==='filter-repeat'?`<div class="list-header"><strong>Repeating</strong></div><div class="list-item"><strong>Call Mum</strong><span class="list-time">Every Sunday · 18:00</span></div><div class="list-item"><strong>Plan the week</strong><span class="list-time">Every Monday · 09:00</span></div>`:`<div class="empty-day"><div><h2>No completed reminders in this demo.</h2><p>Completed occurrences stay in their reminder’s history.</p></div></div>`;return}if(name==='save-reminder'){const title=$('#rem-title');if(!title.value.trim()){title.setAttribute('aria-invalid','true');title.focus();return}go('reminders');toast('Reminder saved · Demo only','Undo');return}if(name==='snooze'){toast('This occurrence snoozed. The repeat stays on schedule · Demo only','Undo');return}if(name==='skip'){toast('Next occurrence skipped · Demo only','Undo');return}if(name==='delete-reminder'){toast('Reminder deleted · Demo only','Undo');return}if(name==='log-session'){quickModal('note: docs: Make the setup guide easier to follow');return}if(name==='move-note'){quickModal('note for Sidefolk: Keep the full action visible.');return}if(name==='copy-week'||name==='copy-notebook'){toast('Markdown preview ready · Demo only');return}if(name==='labs'){openInfo('Labs','Quick actions and Start session are beta and off by default. Turning them on never changes permission policy.');return}if(name==='host-matrix'){openInfo('Host capability matrix','Terminal.app: exact tab (tty). iTerm2: exact tab (tty). Ghostty 1.3+: bring forward and select the session there. WezTerm: bring forward. VS Code / Cursor: bring the project window forward, else the app. Warp / Claude desktop: bring forward. tmux / ssh / unknown: copy attach command. Ended session: resume in the default terminal.');return}if(name==='connect'||name==='repair'||name==='codex-setup'){openInfo('Review connection changes','Production must show the exact files and entries to change, a backup path and a confirmation before installation. This demo does not change any configuration.');return}if(name==='more-reminder'){openInfo('Reminder actions','Edit · Snooze · Skip next · History · Delete. Production uses an anchored keyboard-accessible menu. Two actions remain visible on a list row.');return}const messages={'open-claude':'Demo only · Opens Claude Code to receive the first live event.','open-session':'Demo only · Opens the exact supported host or an honest fallback.','continue-session':'Demo only · Continue is offered only for an ended session.','overlay-done':'Reminder completed · Demo only','overlay-note':'Noted in Log · Demo only','overlay-snooze':'Snoozed 10 minutes · Demo only','discard':'Draft discarded · Demo only','notification-settings':'Demo only · Opens macOS notification settings.','restore':'Demo only · Preview the backup and restart before restoring.','finder':'Demo only · Reveals local files in Finder.','retry':'Demo only · Retrying the failed read.','export':'Demo only · Choose a notebook, Your week, or all entries.','report':'Demo only · Report preview redacts names, home paths and tokens.','project-filter':'Demo only · Filter entries by the project they belong to.','clear-history':'Demo only · Clear asks before removing the session journal.','uninstall':'Demo only · Review integrations to remove. Keep data is selected by default.','new-notebook':'Demo only · New notebook asks for a name.','edit-note':'Demo only · Edit in place, preserve the draft until Save or Cancel.','reset-position':'Position reset · Demo only','week-setting':'Demo only · Friday 16:00, adjustable or off.','snooze-pick':'Demo only · Pick a date and time for this occurrence.'};toast(messages[name]||'Interaction shown for design review · Demo only');}
function openInfo(title,text){const d=document.createElement('dialog');d.className='quick-dialog';d.innerHTML='<h2></h2><p class="muted"></p><div class="spacer"></div><button class="btn" autofocus>Close</button>';d.querySelector('h2').textContent=title;d.querySelector('p').textContent=text;d.querySelector('button').onclick=()=>d.close();d.onclose=()=>d.remove();document.body.append(d);d.showModal();}
function go(to){screen=to;theme=to.endsWith('-dark')?'dark':theme;const p=new URLSearchParams({screen:to,theme});history.pushState(null,'','?'+p);render();if(matchMedia('(max-width:820px)').matches&&$('.detail-pane'))$('#rem-title')?.focus();else $('.page h1, .settings-content h1, .setup-form h1')?.focus({preventScroll:true});}
function render(){document.documentElement.dataset.theme=theme;document.body.classList.toggle('native-preview',params.get('native')==='1');const root=$('#root');if(!screen){root.innerHTML=`<main class="gallery"><header class="gallery-head">${brand()}<span class="eyebrow">Design handoff / 25 October 2026</span></header><h1>Useful every day.<br>Distinctly Sidefolk.</h1><p class="intro">A complete proposal for a calmer, more personal application. Explore the screens below, then follow the editable prototype and implementation specification.</p><nav><a href="README.md">Read the handoff</a><a href="HANDOFF.md">Implementation detail</a><a href="?screen=today">Open prototype ${icon('next')}</a></nav><div class="gallery-grid">${specs.map(([s,t,d],i)=>`<a class="gallery-card" href="?screen=${s}"><img src="images/${String(i+1).padStart(2,'0')}-${s}.png" alt="Design render: ${t}" loading="lazy"><h2>${String(i+1).padStart(2,'0')} · ${t}</h2><p>${d}</p></a>`).join('')}</div><p class="gallery-footer">Design proposal, with illustrative data. No native services, tools, notifications or global settings are connected. All interactions are local and reset on reload.</p></main>`;return}const canonical=screen==='today-dark'||screen==='narrow'||['quick-add','quick-reminder','quick-ambiguity','notebook-choice'].includes(screen)?'today':screen==='settings-dark'?'settings':screen;let content=({cover, today:()=>today(),calm:()=>today(true),reminders:()=>reminders(), 'reminder-edit':()=>reminders(true),'work-log':log,week,sessions,request:()=>request(),'request-diff':()=>request(true),setup:()=>setup(1),'setup-notifications':()=>setup(2),'setup-tools':()=>setup(3),settings,companion,agents,privacy,desktop,components,states,'repeat-editor':repeatEditor,'request-released':releasedRequest,'request-long':longRequest,'desktop-spark':()=>desktop().replaceAll('assets/pip-','assets/spark-').replaceAll('alt="Pip,','alt="Spark,').replace('Hide Pip','Hide Spark'),'control-states':controlStates,'new-reminder':newReminder,'setup-disconnected':setupDisconnected}[canonical]||cover)();const i=Math.max(0,specs.findIndex(s=>s[0]===screen));const prev=specs[(i+specs.length-1)%specs.length][0];const next=specs[(i+1)%specs.length][0];root.innerHTML=`<div class="board" data-screen="${screen}"><header class="board-top"><span class="eyebrow">Sidefolk / ${String(i+1).padStart(2,'0')} / ${titles[screen] || screen}</span><div class="board-controls"><a href="index.html">All screens</a><button data-action="theme">${theme==='dark'?'Light':'Dark'} theme</button><span class="prevnext"><a href="?screen=${prev}">←</a> &nbsp; <a href="?screen=${next}">→</a></span></div></header>${content}<footer class="board-footer"><span>${specs[i][2]}</span><span>Design proposal · Sample data · 25 Oct 2026</span></footer></div>`;if($('.long-operation')){$('.long-operation').addEventListener('scroll',e=>{const op=e.target;if(op.scrollTop+op.clientHeight>=op.scrollHeight-2&&!$('.request-foot [data-action=allow]')){$('.request-foot .row').insertAdjacentHTML('beforeend',btn('Allow once','allow','primary'));$('.request-content .pill').textContent='Complete operation shown';$('.request-content .pill').classList.remove('outline');$('.request-content .pill').nextElementSibling.textContent='All 120 lines are now shown.';}});}if($('#new-note')){$('#new-note').value=demo.noteDraft;if(demo.noteDraft)$('#note-editor').hidden=false;}if(screen==='quick-add')quickModal();if(screen==='quick-reminder')quickModal('Remind me tomorrow at 9 to review the draft');if(screen==='quick-ambiguity')quickModal('Remind me at 3 to review the draft');if(screen==='notebook-choice')quickModal('note for Evaluation: Prefer the simpler flow');}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el || el.closest('dialog'))return;if(el.dataset.go){go(el.dataset.go);return}if(el.dataset.themeChoice){theme=el.dataset.themeChoice==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):el.dataset.themeChoice;render();return}if(el.dataset.pet){demo.pet=el.dataset.pet;render();return}if(el.dataset.book){demo.notebook=el.dataset.book;render();document.querySelectorAll('#log-entries .entry').forEach(x=>x.hidden=demo.notebook!=='All entries'&&x.dataset.notebook!==demo.notebook);$('#notebook-name')?.focus();return}if(el.dataset.complete){let id=el.dataset.complete;if(demo.completed.has(id))demo.completed.delete(id);else demo.completed.add(id);el.classList.toggle('done',demo.completed.has(id));el.setAttribute('aria-pressed',demo.completed.has(id));toast('Reminder completed · Demo only','Undo');return}if(el.dataset.action==='theme'){theme=theme==='dark'?'light':'dark';render();return}if(el.dataset.action)action(el.dataset.action,el)});
document.addEventListener('input',e=>{if(e.target.id==='new-note')demo.noteDraft=e.target.value;if(e.target.id==='rem-date'||e.target.id==='rem-time'){const date=$('#rem-date').value;const time=$('#rem-time').value;$('.detail-pane .preview strong').textContent=`${date} at ${time}`;}if(e.target.id==='log-search'){const v=e.target.value.toLowerCase();document.querySelectorAll('#log-entries .entry').forEach(x=>x.hidden=v&&!x.textContent.toLowerCase().includes(v));}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!document.querySelector('dialog[open]'))quickModal('')}if((e.metaKey||e.ctrlKey)&&e.key===','){e.preventDefault();go('settings')}if((e.metaKey||e.ctrlKey)&&e.key==='z'&&!e.target.closest('input,textarea,[contenteditable]')){const t=$('.toast');if(t){e.preventDefault();t.remove();toast('Change undone · Demo only')}}});
window.addEventListener('popstate',()=>{const p=new URLSearchParams(location.search);screen=p.get('screen')||'';theme=p.get('theme')||'light';render()});
render();
function repeatEditor(){return reminders(true).replace('value="Review launch notes"','value="Call Mum"').replace('value="15:00"','value="18:00"').replace('<option>Weekly</option>','<option selected>Weekly</option>').replace('<option>Does not repeat</option>','<option>Does not repeat</option>').replace('Today, 25 Oct at 15:00','Every Sunday at 18:00').replace('Move this reminder without changing its title.','The next repeat keeps Sunday at 18:00.').replace('<div class="row"><button class="btn primary" data-action="save-reminder">','<fieldset class="scope"><legend>Apply changes to</legend><label><input type="radio" name="scope" checked> This one</label><label><input type="radio" name="scope"> All future</label></fieldset><div class="row"><button class="btn primary" data-action="save-reminder">').replace('<div class="divider"></div><h3>History</h3>',btn('Skip next','skip','quiet')+'<div class="divider"></div><h3>History</h3>').replace('class="list-item selected"','class="list-item"').replace('<strong>Call Mum</strong>','<strong>Call Mum</strong><span class="pill" style="margin-left:8px">Editing</span>');}
function releasedRequest(){const saved=demo.request;demo.request='Moved to your terminal';let html=request();demo.request=saved;return html.replace('Demo only. No answer was sent to a tool.','Claude is asking there. This request can no longer be answered here.').replace('Claude is asking there. This request can no longer be answered here.</p>','Claude is asking there. This request can no longer be answered here.</p>'+btn('Open session','open-session'));}
function longRequest(){return shell(`${head('Review request','Every line matters.',routeBtn('All sessions','sessions','quiet'))}<div class="request-grid"><aside class="request-context">${status('alert')}<h3>sidefolk</h3><p class="meta">Tighten reminder parsing</p><dl><dt>Tool</dt><dd>Claude Code</dd><dt>Host</dt><dd>Terminal.app · ttys004</dd><dt>Operation</dt><dd>Write file</dd><dt>File</dt><dd class="mono">src/reminder-fixtures.json</dd></dl></aside><section class="request-content"><span class="eyebrow">Write file · 120 lines</span><h2>Review the complete file.</h2><p class="muted">All content must be shown before Allow becomes available.</p><div class="long-operation" tabindex="0" aria-label="Complete file content, scroll to review">${Array.from({length:120},(_,i)=>`<div><span class="line-number">${i+1}</span><code>${i===0?'[':i===119?']':`  { "id": ${i}, "text": "Reminder fixture ${i}", "hour": 9 }${i===118?'':','}`}</code></div>`).join('')}</div><div class="row" style="margin-top:16px"><span class="pill outline">More content below</span><span class="meta">Keep reviewing to see the whole operation.</span></div><div class="request-foot"><div class="row">${btn('Decline','decline')}${btn('Answer in terminal','answer-terminal','quiet')}</div><p class="safe-note">Allow once appears only when the complete operation has been shown.</p></div></section></div>`,'sessions');}
function controlStates(){return shell(`${head('Every interaction, considered.','Default controls are only the beginning.')}<div class="state-grid"><section class="state-sample"><span class="eyebrow">Default / Hover / Focus</span><div class="row" style="margin-top:16px">${btn('Save','demo','primary')}<button class="btn primary demo-hover">Save</button><button class="btn primary demo-focus">Save</button></div><p class="footnote">Hover stays subtle. Focus is a separate 3px ring.</p></section><section class="state-sample"><span class="eyebrow">Disabled / Pending</span><div class="row" style="margin-top:16px"><button class="btn" disabled>Allow once</button><button class="btn primary" disabled>Saving…</button></div><p class="footnote">Give the reason next to unavailable actions.</p></section><section class="state-sample"><span class="eyebrow">Validation</span><label class="label" for="invalid-time" style="margin-top:12px">Time</label><input id="invalid-time" class="field invalid" value="25:30" aria-invalid="true" aria-describedby="time-error"><p id="time-error" class="error-copy" style="color:var(--error)">Choose a time between 00:00 and 23:59.</p></section><section class="state-sample"><span class="eyebrow">Persistence failed</span><h3 style="margin-top:12px">I couldn’t save that reminder.</h3><p>Your draft is still here.</p><div class="row">${btn('Try again','retry','primary')}${btn('Keep editing','demo','quiet')}</div></section><section class="state-sample"><span class="eyebrow">Saved / Move / Undo</span><div class="preview" style="margin-top:12px"><strong>Noted in Log.</strong><div class="row" style="margin-top:8px">${btn('Move','move-note','quiet')}${btn('Undo','undo','quiet')}</div></div><p class="footnote">Undo stays available. It does not disappear on a timer.</p></section><section class="state-sample"><span class="eyebrow">Selected / Pressed</span><div class="segmented" style="margin-top:16px"><button aria-pressed="true">Upcoming</button><button aria-pressed="false">Completed</button></div><div class="row" style="margin-top:16px">${toggle('Selected example')}<span>Sound cues on</span></div></section><section class="state-sample"><span class="eyebrow">Unsupported / Ask</span><h3 style="margin-top:12px">Which days should this repeat?</h3><p>That schedule needs one more detail. Nothing has been saved.</p>${btn('Choose days','demo','quiet')}</section><section class="state-sample"><span class="eyebrow">Reduced motion / Large text</span><h3 style="margin-top:12px">The same information, with room to grow.</h3><p>Static pose + visible word. Text and rows scale together.</p></section></div>`,'today');}
function newReminder(){let html=reminders(true);const cut=html.indexOf('<div class="divider"></div><h3>Snooze');if(cut!==-1)html=html.slice(0,cut)+'</aside></div></div></main></div>';return html.replace('Edit reminder','New reminder').replace('value="Review launch notes"','value="" placeholder="What would you like to remember?"').replace('Save changes','Save reminder').replace('class="list-item selected"','class="list-item"');}
function setupDisconnected(){return setup(3).replace('Connected and waiting for the first session','Not connected').replace('Setup files are installed. Open Claude Code to verify a live event.','Connect to see session status and requests here.').replace(btn('Open Claude Code','open-claude','primary'),btn('Connect Claude Code…','connect','primary')).replace('Waiting for the first live event.','We show the files to change and keep a backup.').replace(routeBtn('Continue to Today','today'),'');}
